async function renderCatalog() {
  updateTitle('Katalog'); const p=new URLSearchParams(location.search), q=(p.get('q')||'').slice(0,80), category=p.get('category')||'', sort=p.get('sort')||'newest', page=Math.max(1,Number(p.get('page')||1));
  const data=await api('/catalog?'+new URLSearchParams({q,category,sort,page:String(page)}));
  const categoryTitle=state.config.categories.find(c=>c.id===category)?.name;
  const urlWith = (name,value) => { const x=new URLSearchParams(location.search); if(value) x.set(name,value); else x.delete(name); if(name!=='page') x.delete('page'); return '/catalog'+(x.size?'?'+x.toString():''); };
  return `${crumbs([categoryTitle||'Katalog'])}<div class="page-heading"><span class="eyebrow">Marketuz tanlovi</span><h1>${q?`“${esc(q)}” uchun natijalar`:esc(categoryTitle||'Barcha mahsulotlar')}</h1><p>O‘zingiz uchun to‘g‘ri tanlovni toping. Mahsulotlar sotuvchilar tomonidan taqdim etiladi.</p></div><div class="catalog-layout"><aside class="filter-panel"><h3>Kategoriyalar</h3><a href="${urlWith('category','')}" data-link class="${!category?'active':''}">Hammasi <span>✳</span></a>${state.config.categories.map(c=>`<a href="${urlWith('category',c.id)}" data-link class="${c.id===category?'active':''}">${esc(c.name)} <span>✳</span></a>`).join('')}</aside><div><div class="catalog-top"><span>${data.total} ta mahsulot topildi</span><select id="catalog-sort" aria-label="Saralash"><option value="newest" ${sort==='newest'?'selected':''}>Eng yangilar</option><option value="popular" ${sort==='popular'?'selected':''}>Ommabop</option><option value="price_asc" ${sort==='price_asc'?'selected':''}>Arzonidan</option><option value="price_desc" ${sort==='price_desc'?'selected':''}>Qimmatidan</option></select></div>${data.products.length?`<div class="products-grid">${data.products.map(productCard).join('')}</div>`:empty('Hozircha mahsulot topilmadi','Boshqa so‘z yoki kategoriyani sinab ko‘ring.','Barcha mahsulotlar','/catalog','search')}${data.pages>1?`<div class="pagination">${Array.from({length:Math.min(data.pages,8)},(_,i)=>`<a href="${urlWith('page',i+1)}" data-link class="${page===i+1?'active':''}">${i+1}</a>`).join('')}</div>`:''}</div></div>`;
}
async function renderProduct(id) {
  const { product:p }=await api('/products/'+encodeURIComponent(id)); state.products.set(String(p.id),p); updateTitle(p.name);
  const related=await api('/catalog?category='+encodeURIComponent(p.category));
  const c=state.config.categories.find(x=>x.id===p.category);
  return `${crumbs(['Katalog','/catalog'],[c?.name||'Mahsulot','/catalog?category='+p.category],[p.name])}<div class="detail-grid"><div>${img(p.image_url,p.name,'class="detail-image" loading="eager"')}</div><section class="detail-copy"><span class="eyebrow">${esc(c?.name||'Marketuz tanlovi')}</span><h1>${esc(p.name)}</h1><p class="lead">${esc(p.description)}</p><div class="detail-price">${money(p.price)} ${p.old_price?`<s>${money(p.old_price)}</s>`:''}</div><span class="in-stock">${p.stock>0?`● Omborda ${p.stock} dona mavjud`:'Hozircha tugagan'}</span><div class="detail-meta"><div><span>Kategoriya</span><strong>${esc(c?.name||'—')}</strong></div><div><span>Sotuvchi</span><strong>${esc(p.seller_name||'Marketuz tanlovi')}</strong></div><div><span>Yetkazib berish</span><strong>Manzilga qarab tasdiqlanadi</strong></div><div><span>To‘lov</span><strong>${state.config.payments.length>1?'Click, Payme yoki yetkazilganda':'Yetkazilganda'}</strong></div></div><div class="detail-actions"><button class="btn btn-primary" data-action="add-cart" data-id="${p.id}" ${p.stock<1?'disabled':''}>${icon('bag')} Savatga qo‘shish</button><button class="icon-button" data-action="favorite" data-id="${p.id}" aria-label="Sevimlilarga qo‘shish">${icon('heart')}</button></div><div class="share-actions"><button data-action="share" data-id="${p.id}">${icon('sparkle')} Ulashish</button><a href="https://t.me/share/url?url=${encodeURIComponent(location.origin+'/product/'+p.id)}&text=${encodeURIComponent(p.name)}" target="_blank" rel="noopener noreferrer">Telegram</a><a href="https://wa.me/?text=${encodeURIComponent(p.name+' '+location.origin+'/product/'+p.id)}" target="_blank" rel="noopener noreferrer">WhatsApp</a></div>${p.external_links?.length?`<div class="external-links">${p.external_links.map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a>`).join('')}</div>`:''}<p class="summary-note">Buyurtma va yetkazish tafsilotlari manzil bo‘yicha tasdiqlanadi.</p></section></div><section class="section">${sectionHead('Sizga ham yoqishi mumkin','O‘xshash topilmalar','','/catalog?category='+p.category,'Ko‘proq ko‘rish')}<div class="products-grid">${related.products.filter(x=>String(x.id)!==String(p.id)).slice(0,4).map(productCard).join('')}</div></section>`;
}
async function loadCart() {
  const entries=state.cart.filter(x=>Number.isSafeInteger(Number(x.id))&&Number(x.qty)>0);
  const found=await Promise.all(entries.map(async item=>{ try { const p=state.products.get(String(item.id))||(await api('/products/'+item.id)).product; state.products.set(String(item.id),p); return {...p,qty:Math.max(1,Math.min(20,Number(item.qty)))}; } catch { return null; } }));
  return found.filter(Boolean);
}
const summary = (products,checkout=false) => { const count=products.reduce((n,p)=>n+p.qty,0), total=products.reduce((n,p)=>n+p.price*p.qty,0); return `<aside class="summary"><h2>Buyurtma xulosasi</h2><div class="summary-row"><span>Mahsulotlar (${count})</span><strong>${money(total)}</strong></div><div class="summary-row"><span>Yetkazib berish</span><strong>Alohida aniqlanadi</strong></div><div class="summary-row summary-total"><span>Mahsulotlar jami</span><strong>${money(total)}</strong></div>${checkout?'':`<a href="/checkout" data-link class="btn btn-primary">Buyurtmaga o‘tish</a>`}<p class="summary-note">Yetkazish narxi va yakuniy shartlar siz bilan bog‘langandan keyin tasdiqlanadi. Onlayn to‘lov faqat faollashtirilgan provayder orqali amalga oshiriladi.</p></aside>`; };
async function renderCart() {
  updateTitle('Savat'); const p=await loadCart();
  return `${crumbs(['Savat'])}<div class="page-heading"><span class="eyebrow">Sizning tanlovingiz</span><h1>Savatim</h1><p>Yoqtirgan mahsulotlaringizni bir joyda ko‘ring.</p></div>${!p.length?empty('Savat hozircha bo‘sh','Mahsulotlarni ko‘rib, o‘zingizga yoqqanini savatga qo‘shing.','Katalogni ko‘rish','/catalog'): `<div class="cart-layout"><div class="cart-list">${p.map(x=>`<article class="cart-item">${img(x.image_url,x.name)}<div><a href="/product/${x.id}" data-link><h3>${esc(x.name)}</h3></a><small>${esc(state.config.categories.find(c=>c.id===x.category)?.name||'Marketuz')}</small><div class="item-price">${money(x.price)}</div></div><div class="cart-right"><strong>${money(x.price*x.qty)}</strong><div class="quantity-picker"><button data-action="cart-qty" data-id="${x.id}" data-delta="-1" aria-label="Soni kamaytirish">−</button><span>${x.qty}</span><button data-action="cart-qty" data-id="${x.id}" data-delta="1" aria-label="Soni oshirish">+</button></div><button class="text-button" data-action="cart-remove" data-id="${x.id}">O‘chirish</button></div></article>`).join('')}</div>${summary(p)}</div>`}`;
}
async function renderCheckout() {
  updateTitle('Buyurtma'); const products=await loadCart();
  if(!products.length) return `${crumbs(['Buyurtma'])}<div class="page-heading"><h1>Buyurtma</h1></div>${empty('Savat bo‘sh','Buyurtma berish uchun mahsulot tanlang.','Katalogga o‘tish','/catalog')}`;
  if(!state.user) { state.authNext='/checkout'; return `${crumbs(['Buyurtma'])}<div class="page-heading"><h1>Davom etish uchun kiring</h1></div>${renderAuth('login',true)}`; }
  return `${crumbs(['Savat','/cart'],['Buyurtma'])}<div class="page-heading"><span class="eyebrow">Yakunlash</span><h1>Buyurtma ma’lumotlari</h1><p>Manzilingizni to‘ldiring. ${state.config.shipping==='included'?'Yetkazish mahsulot narxiga kiritilgan.':'Yetkazish narxi va imkoniyati operator tomonidan alohida tasdiqlanadi.'}</p></div><div class="checkout-layout"><form class="form-card" data-form="checkout"><h2>Qabul qiluvchi</h2><div class="form-grid"><label class="field">Ism va familiya<input name="recipient" value="${esc(state.user.full_name)}" maxlength="120" required></label><label class="field">Telefon raqami<input name="phone" type="tel" value="${esc(state.user.phone||'')}" placeholder="+998 90 123 45 67" required></label><label class="field">Viloyat / shahar<select name="region" required><option value="">Hududni tanlang</option>${state.config.regions.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('')}</select></label><label class="field">Tuman / shahar<input name="district" placeholder="Masalan, Kasbi tumani" required maxlength="100"></label><label class="field full">To‘liq manzil<input name="address" placeholder="Ko‘cha, uy, xonadon va mo‘ljal" required maxlength="300"></label><label class="field full">Izoh (ixtiyoriy)<textarea name="note" maxlength="500" placeholder="Yetkazuvchi uchun qo‘shimcha ma’lumot"></textarea></label><label class="field full">To‘lov usuli<select name="paymentMethod" required>${state.config.payments.map(x=>`<option value="${x}">${x==='cod'?'Yetkazilganda':x==='click'?'Click':'Payme'}</option>`).join('')}</select></label><div class="hint-box full">${icon('truck')} ${state.config.shipping==='included'?'Yetkazish mahsulot narxiga kiritilgan.':'Yetkazish xizmati va narxi manzil tasdiqlangach belgilanadi.'} UzPost jo‘natmasi hozir avtomatik yaratilmaydi.</div><div class="field full"><label class="checkbox-row"><input type="checkbox" required name="agree"> Buyurtma shartlari, <a href="/terms" data-link>foydalanish shartlari</a> va <a href="/privacy" data-link>maxfiylik siyosati</a> bilan tanishganimni tasdiqlayman.</label></div><button class="btn btn-primary full" type="submit">Buyurtmani yuborish</button></div></form>${summary(products,true)}</div>`;
}
function renderAuth(mode='login',embedded=false) {
  const register=mode==='register'; updateTitle(register?'Ro‘yxatdan o‘tish':'Kirish');
  return `${embedded?'':crumbs(['Kirish'])}<div class="auth-shell"><div class="auth-art"><div><span class="eyebrow eyebrow-light">Marketuz oilasi</span><h2>Yangi topilmalar shu yerdan boshlanadi.</h2><p>Sevimli mahsulotlaringiz, buyurtmalar va sotuvchi markazi bitta joyda.</p></div></div><form class="auth-form" data-form="${register?'register':'login'}"><span class="eyebrow">Xush kelibsiz</span><h1>${register?'Hisob ochish':'Hisobga kirish'}</h1><p>${register?'Xaridlaringizni qulay boshqarish uchun hisob yarating.':'Davom etish uchun ma’lumotlaringizni kiriting.'}</p>${register?'<label class="field">Ism va familiya<input name="name" autocomplete="name" required minlength="2" maxlength="100"></label>':''}<label class="field">Email manzil<input type="email" name="email" autocomplete="email" required maxlength="200" placeholder="name@example.com"></label><label class="field">Parol<input type="password" name="password" autocomplete="${register?'new-password':'current-password'}" required minlength="${register?10:1}" placeholder="${register?'Kamida 10 ta belgi':'Parolingiz'}"></label>${register?'<label class="checkbox-row"><input name="agree" type="checkbox" required> <span><a href="/terms" data-link>Foydalanish shartlari</a> va <a href="/privacy" data-link>maxfiylik siyosati</a> bilan tanishdim.</span></label>':''}<button class="btn btn-primary" type="submit">${register?'Ro‘yxatdan o‘tish':'Kirish'}</button><div class="auth-switch">${register?'Hisobingiz bormi?':'Hali hisobingiz yo‘qmi?'} <button type="button" data-action="auth-mode" data-mode="${register?'login':'register'}">${register?'Kirish':'Ro‘yxatdan o‘tish'}</button></div></form></div>`;
}
async function renderFavorites() {
  updateTitle('Sevimlilar'); let products=[];
  if(state.user) products=(await api('/favorites')).products; else products=(await Promise.all([...state.favorites].map(async id=>{try {return state.products.get(id)||(await api('/products/'+id)).product;}catch{return null;}}))).filter(Boolean);
  return `${crumbs(['Sevimlilar'])}<div class="page-heading"><span class="eyebrow">Sizning tanlovingiz</span><h1>Sevimlilar</h1><p>Yoqqan mahsulotlarni shu yerda saqlab boring.</p></div>${products.length?`<div class="products-grid">${products.map(productCard).join('')}</div>`:empty('Sevimlilar hozircha bo‘sh','Mahsulot kartasidagi yurakchani bosing, ular shu yerda paydo bo‘ladi.','Katalogni ko‘rish','/catalog','heart')}`;
}
async function renderAccount() {
  if(!state.user) return renderAuth(new URLSearchParams(location.search).get('mode')==='register'?'register':'login');
  updateTitle('Shaxsiy kabinet'); const tab=new URLSearchParams(location.search).get('tab')||'profile';
  let content='';
  if(tab==='orders') { const {orders}=await api('/orders'); content=orders.length?orders.map(o=>`<article class="order-card"><div class="order-head"><div><strong>Buyurtma #${esc(o.id.slice(0,8).toUpperCase())}</strong><small>${dateText(o.created_at)} · ${esc(o.region)}, ${esc(o.district)}</small></div><span class="status ${esc(o.status)}">${esc(labelStatus[o.status]||o.status)}</span></div><div class="order-items">${o.items.map(i=>img(i.image_url,i.title,`title="${esc(i.title)}"`)).join('')}</div><div class="profile-row"><span>Mahsulotlar jami</span><strong>${money(o.subtotal)}</strong></div>${o.tracking_number?`<p class="summary-note">Kuzatuv raqami: <strong>${esc(o.tracking_number)}</strong></p>`:''}<p class="summary-note">Yetkazish narxi: ${state.config.shipping==='included'?'mahsulot narxiga kiritilgan':'operator tomonidan aniqlanadi'}.</p>${o.status==='awaiting_payment'?`<button data-action="resume-payment" data-id="${esc(o.id)}" class="small-btn">To‘lovni davom ettirish</button>`:''}${o.payment_status!=='paid'&&['awaiting_payment','new','accepted','packing'].includes(o.status)?`<button data-action="cancel-order" data-id="${esc(o.id)}" class="small-btn reject">Buyurtmani bekor qilish</button>`:''}</article>`).join(''):empty('Buyurtmalar yo‘q','Birinchi topilmangiz sizni kutmoqda.','Katalogga o‘tish','/catalog','box'); }
  else if(tab==='security') content=`<div class="profile-card"><h2>Parolni yangilash</h2><form data-form="password" class="form-grid"><label class="field full">Joriy parol<input name="currentPassword" type="password" required></label><label class="field full">Yangi parol<input name="newPassword" type="password" minlength="10" required></label><button class="btn btn-primary" type="submit">Parolni saqlash</button></form></div>`;
  else content=`<div class="profile-card"><h2>Shaxsiy ma’lumotlar</h2><form data-form="profile" class="form-grid"><label class="field">Ism va familiya<input name="name" value="${esc(state.user.full_name)}" required></label><label class="field">Telefon<input name="phone" type="tel" value="${esc(state.user.phone||'')}" placeholder="+998 ..."></label><label class="field full">Email<input value="${esc(state.user.email)}" disabled><small>Emailni o‘zgartirish uchun qo‘llab-quvvatlash xizmatiga murojaat qiling.</small></label><button class="btn btn-primary" type="submit">Saqlash</button></form><div class="profile-row"><span>Hisob turi</span><strong>${state.user.role==='admin'?'Administrator':state.user.role==='seller'?'Sotuvchi':'Xaridor'}</strong></div><div class="profile-row"><span>Sotuvchi holati</span><strong>${esc(labelStatus[state.user.seller_status]||'Yuborilmagan')}</strong></div></div>`;
  return `${crumbs(['Shaxsiy kabinet'])}<div class="page-heading"><span class="eyebrow">Kabinet</span><h1>Salom, ${esc(state.user.full_name.split(' ')[0])}!</h1><p>Hisobingiz va buyurtmalaringiz bir joyda.</p></div><div class="account-grid"><nav class="account-side"><a href="/account?tab=profile" data-link class="${tab==='profile'?'active':''}">${icon('user')} Ma’lumotlarim</a><a href="/account?tab=orders" data-link class="${tab==='orders'?'active':''}">${icon('box')} Buyurtmalarim</a><a href="/favorites" data-link>${icon('heart')} Sevimlilar</a><a href="/account?tab=security" data-link class="${tab==='security'?'active':''}">${icon('lock')} Xavfsizlik</a><a href="/seller" data-link>${icon('store')} Sotuvchi markazi</a>${state.user.role==='admin'?`<a href="/admin" data-link>${icon('sliders')} Admin panel</a>`:''}<a href="#" data-action="logout">${icon('logout')} Chiqish</a></nav><div>${content}</div></div>`;
}

const sellerIntro = `<div class="delivery-hero seller-hero"><span class="eyebrow eyebrow-light">Sotuvchilar uchun</span><h1>Mahsulotlaringizni ko‘proq odamlar bilan tanishtiring.</h1><p>O‘z do‘koningizni boshqaring: mahsulotlarni joylang, buyurtmalarni kuzating va o‘sish uchun yangi qadam tashlang.</p></div><div class="steps"><div class="step"><span class="benefit-icon">${icon('user')}</span><strong>Ariza yuboring</strong><p>Hisobingizdan sotuvchi bo‘lish uchun so‘rov qoldiring.</p></div><div class="step"><span class="benefit-icon">${icon('store')}</span><strong>Mahsulot qo‘shing</strong><p>Admin tasdiqlagach o‘z katalogingizni to‘ldiring.</p></div><div class="step"><span class="benefit-icon">${icon('box')}</span><strong>Buyurtmalarni boshqaring</strong><p>Buyurtma satrlarini tayyorlash holatiga o‘tkazing.</p></div></div>`;
async function renderSeller() {
  updateTitle('Sotuvchi markazi');
  if(!state.user) return `${sellerIntro}${empty('Sotuvchi bo‘lishga tayyormisiz?','Ariza topshirish uchun avval hisobga kiring.','Hisobga kirish','/account','store')}`;
  state.user=(await api('/me')).user;
  if(state.user.role==='admin') return `${sellerIntro}${empty('Administrator hisobidasiz','Sotuvchi arizalarini administrator panelida boshqaring.','Admin panelga o‘tish','/admin','sliders')}`;
  if(state.user.role !== 'seller') return `${sellerIntro}<div class="form-card seller-apply"><h2>${state.user.seller_status==='pending'?'So‘rovingiz ko‘rib chiqilmoqda':'Sotuvchi bo‘lish uchun ariza'}</h2><p class="summary-note">${state.user.seller_status==='pending'?'Administrator arizangizni tekshiradi. Tasdiqlangach bu bo‘limda boshqaruv paneli ochiladi.':'Sotuvchi arizasi administratorga yuboriladi. Mahsulotlar katalogga chiqishidan oldin tekshiriladi.'}</p>${state.user.seller_status==='pending'?'':`<button class="btn btn-primary" data-action="seller-request">Ariza yuborish</button>`}</div>`;
  const tab=new URLSearchParams(location.search).get('tab')||'products';
  const [p,o]=await Promise.all([api('/seller/products'),api('/seller/orders')]); state.sellerProducts=p.products; state.sellerOrders=o.items;
  const products=`<div class="dashboard-heading"><h1>Mahsulotlarim</h1><button class="btn btn-primary" data-action="seller-new">Yangi mahsulot qo‘shish</button></div><div class="dashboard-card" id="seller-form-card" hidden><h2 id="seller-form-title">Mahsulot qo‘shish</h2><form data-form="seller-product" class="form-grid"><label class="field full">Mahsulot nomi<input name="name" required minlength="3" maxlength="180"></label><label class="field full">Tavsif<textarea name="description" maxlength="2000" placeholder="Mahsulotning asosiy xususiyatlari"></textarea></label><label class="field">Kategoriya<select name="category" required><option value="">Tanlang</option>${state.config.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label class="field">Mavjud soni<input name="stock" type="number" min="0" max="100000" required></label><label class="field">Narxi (so‘m)<input name="price" type="number" min="1000" required></label><label class="field">Eski narxi (ixtiyoriy)<input name="oldPrice" type="number" min="0"></label><label class="field full">Rasm uchun HTTPS havola<input name="image" type="url" placeholder="https://..." required><small>Mahsulot rasmini HTTPS havola orqali qo‘shing.</small></label><div class="field full"><strong>Mahsulotga tashqi havolalar</strong><small>Rasmiy sahifa, qo‘llanma yoki qo‘shimcha taklif uchun 3 tagacha HTTPS havola.</small></div>${[1,2,3].map(n=>`<label class="field">${n}-havola nomi<input name="linkLabel${n}" maxlength="45" placeholder="Masalan, batafsil"></label><label class="field">${n}-havola URL<input type="url" name="linkUrl${n}" placeholder="https://..."></label>`).join('')}<div class="hint-box full">Mahsulot qo‘shilgach yoki tahrirlangach, administrator tasdiqlashini kutadi.</div><button class="btn btn-primary" type="submit">Mahsulotni yuborish</button><button class="btn btn-outline" type="button" data-action="seller-form-close">Bekor qilish</button></form></div><div class="dashboard-card"><h2>Jami ${p.products.length} ta mahsulot</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Mahsulot</th><th>Narxi</th><th>Qoldiq</th><th>Holati</th><th>Amallar</th></tr></thead><tbody>${p.products.length?p.products.map(x=>`<tr><td>${img(x.image_url,x.name)}<strong>${esc(x.name)}</strong></td><td>${money(x.price)}</td><td>${x.stock} dona</td><td><span class="status ${esc(x.status)}">${esc(labelStatus[x.status]||x.status)}</span></td><td><button class="small-btn" data-action="seller-edit" data-id="${x.id}">Tahrirlash</button>${x.status!=='archived'?`<button class="small-btn reject" data-action="seller-archive" data-id="${x.id}">Arxivlash</button>`:''}</td></tr>`).join(''):'<tr><td colspan="5">Hozircha mahsulot yo‘q.</td></tr>'}</tbody></table></div></div>`;
  const orders=`<div class="dashboard-heading"><h1>Buyurtma satrlari</h1></div><div class="dashboard-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Mahsulot</th><th>Qabul qiluvchi</th><th>Hudud</th><th>Buyurtma</th><th>Tayyorlash</th></tr></thead><tbody>${o.items.length?o.items.map(x=>`<tr><td>${img(x.image_url,x.title)}<strong>${esc(x.title)}</strong><br>${x.quantity} dona · ${money(x.price*x.quantity)}</td><td>${esc(x.recipient)}<br>${esc(x.phone)}</td><td>${esc(x.region)}, ${esc(x.district)}</td><td><span class="status ${esc(x.order_status)}">${esc(labelStatus[x.order_status]||x.order_status)}</span></td><td><span class="status ${esc(x.fulfillment_status)}">${esc(labelStatus[x.fulfillment_status]||x.fulfillment_status)}</span>${!['cancelled','delivered'].includes(x.order_status)?`<br><button class="small-btn" data-action="seller-item-status" data-id="${x.id}" data-status="${x.fulfillment_status==='new'?'packing':'ready'}">${x.fulfillment_status==='new'?'Tayyorlanmoqda':x.fulfillment_status==='packing'?'Tayyor':'Tayyor'}</button>`:''}</td></tr>`).join(''):'<tr><td colspan="5">Hozircha buyurtmalar yo‘q.</td></tr>'}</tbody></table></div></div>`;
  return `${crumbs(['Sotuvchi markazi'])}<div class="page-heading"><span class="eyebrow">Mening do‘konim</span><h1>Sotuvchi markazi</h1><p>Mahsulotlar va buyurtmalarni bitta panelda boshqaring.</p></div><div class="dashboard-shell"><nav class="dashboard-nav"><button data-action="seller-tab" data-tab="products" class="${tab==='products'?'active':''}">${icon('grid')} Mahsulotlar</button><button data-action="seller-tab" data-tab="orders" class="${tab==='orders'?'active':''}">${icon('box')} Buyurtmalar</button></nav><div class="dashboard-main">${tab==='orders'?orders:products}</div></div>`;
}
async function renderAdmin() {
  updateTitle('Administrator');
  if(!state.user) return `${crumbs(['Administrator'])}<div class="page-heading"><h1>Administrator paneli</h1></div>${empty('Hisobga kiring','Bu bo‘lim faqat administrator uchun.','Kirish','/account','lock')}`;
  if(state.user.role!=='admin') return `${crumbs(['Administrator'])}<div class="page-heading"><h1>Administrator paneli</h1></div>${empty('Ruxsat yo‘q','Bu bo‘lim faqat administrator uchun.','Bosh sahifaga','/','lock')}`;
  const tab=new URLSearchParams(location.search).get('tab')||'overview';
  const [overview,sellers,products,orders,settings]=await Promise.all([api('/admin/overview'),api('/admin/sellers'),api('/admin/products'),api('/admin/orders'),api('/admin/settings')]);
  state.admin={ overview:overview.stats, sellers:sellers.sellers, products:products.products, orders:orders.orders, settings };
  const s=overview.stats;
  const stats=`<div class="stat-grid"><div class="stat-card"><span>Jami foydalanuvchilar</span><strong>${s.users}</strong></div><div class="stat-card"><span>Faol mahsulotlar</span><strong>${s.active_products}</strong></div><div class="stat-card"><span>Buyurtmalar</span><strong>${s.orders}</strong></div><div class="stat-card"><span>Kutilayotgan tasdiqlar</span><strong>${s.seller_requests+s.pending_products}</strong></div></div>`;
  const sellerTable=`<div class="dashboard-card"><h2>Sotuvchi arizalari</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Foydalanuvchi</th><th>Email</th><th>Holati</th><th>Amallar</th></tr></thead><tbody>${sellers.sellers.length?sellers.sellers.map(x=>`<tr><td><strong>${esc(x.full_name)}</strong></td><td>${esc(x.email)}</td><td><span class="status ${esc(x.seller_status)}">${esc(labelStatus[x.seller_status]||x.seller_status)}</span></td><td>${x.seller_status==='pending'?`<button class="small-btn" data-action="admin-seller" data-id="${x.id}" data-status="approved">Tasdiqlash</button><button class="small-btn reject" data-action="admin-seller" data-id="${x.id}" data-status="rejected">Rad etish</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="4">Arizalar yo‘q.</td></tr>'}</tbody></table></div></div>`;
  const productTable=`<div class="dashboard-card" id="admin-product-card" hidden><h2>Mahsulotni tahrirlash</h2><form data-form="admin-product-details" class="form-grid"><label class="field full">Nom<input name="name" required maxlength="180"></label><label class="field full">Tavsif<textarea name="description" maxlength="2000"></textarea></label><label class="field">Kategoriya<select name="category">${state.config.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label class="field">Qoldiq<input name="stock" type="number" min="0" required></label><label class="field">Narx<input name="price" type="number" min="1000" required></label><label class="field">Eski narx<input name="oldPrice" type="number" min="0"></label><label class="field full">Rasm havolasi<span class="asset-field"><input name="image" data-setting="product.image" required><button type="button" data-action="upload-asset" data-target="product.image">Rasm yuklash</button></span></label>${[1,2,3].map(n=>`<label class="field">${n}-tashqi havola nomi<input name="linkLabel${n}" maxlength="45"></label><label class="field">${n}-tashqi havola URL<input name="linkUrl${n}" type="url"></label>`).join('')}<label class="field">Holat<select name="status">${['active','pending','rejected','archived'].map(v=>`<option value="${v}">${labelStatus[v]}</option>`).join('')}</select></label><button class="btn btn-primary" type="submit">Mahsulotni saqlash</button></form></div><div class="dashboard-card"><div class="dashboard-heading"><h2>Mahsulotlar nazorati</h2><button class="btn btn-primary" data-action="admin-new-product">Mahsulot qo‘shish</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Mahsulot</th><th>Sotuvchi</th><th>Narxi</th><th>Holati</th><th>Amallar</th></tr></thead><tbody>${products.products.map(x=>`<tr><td>${img(x.image_url,x.name)}<strong>${esc(x.name)}</strong></td><td>${esc(x.seller_name||'Platforma katalogi')}</td><td>${money(x.price)}</td><td><span class="status ${esc(x.status)}">${esc(labelStatus[x.status]||x.status)}</span></td><td><button class="small-btn" data-action="admin-edit-product" data-id="${x.id}">Tahrirlash</button>${x.status==='pending'?`<button class="small-btn" data-action="admin-product" data-id="${x.id}" data-status="active">E’lon qilish</button><button class="small-btn reject" data-action="admin-product" data-id="${x.id}" data-status="rejected">Rad etish</button>`:x.status==='active'?`<button class="small-btn reject" data-action="admin-product" data-id="${x.id}" data-status="archived">Yashirish</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;
  const orderTable=`<div class="dashboard-card"><h2>Buyurtmalar</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Buyurtma</th><th>Xaridor</th><th>Manzil</th><th>Mahsulotlar</th><th>Holat va kuzatuv</th></tr></thead><tbody>${orders.orders.length?orders.orders.map(x=>`<tr><td><strong>#${esc(x.id.slice(0,8).toUpperCase())}</strong><br>${dateText(x.created_at)}</td><td>${esc(x.recipient)}<br>${esc(x.phone)}<br>${esc(x.buyer_email)}</td><td>${esc(x.region)} · ${esc(x.district)}<br>${esc(x.address)}</td><td><strong>${money(x.subtotal)}</strong><br><small>Yetkazish alohida</small></td><td><form data-form="admin-order" data-id="${esc(x.id)}"><select name="status" aria-label="Buyurtma holati"><option value="awaiting_payment" ${x.status==='awaiting_payment'?'selected':''} disabled>To‘lov kutilmoqda</option><option value="new" ${x.status==='new'?'selected':''}>Yangi</option>${['accepted','packing','handed_over','in_transit','delivered','cancelled'].map(v=>`<option value="${v}" ${x.status===v?'selected':''}>${esc(labelStatus[v])}</option>`).join('')}</select><input class="input" name="trackingNumber" value="${esc(x.tracking_number||'')}" placeholder="UzPost kuzatuv raqami" maxlength="100"><button class="small-btn" type="submit" ${x.status==='cancelled'?'disabled':''}>Saqlash</button></form></td></tr>`).join(''):'<tr><td colspan="5">Buyurtmalar yo‘q.</td></tr>'}</tbody></table></div></div>`;
  const cmsTabs={brand:['sparkle','Brend va SEO'],seasons:['sparkle','Mavsum va bayram'],categories:['grid','Kategoriyalar'],content:['file','Bosh sahifa'],icons:['grid','Ikonkalar'],legal:['file','Qoidalar va aloqa'],integrations:['shield','Integratsiyalar']};
  return `${crumbs(['Administrator'])}<div class="page-heading"><span class="eyebrow">Boshqaruv</span><h1>Administrator paneli</h1><p>Do‘kon ko‘rinishi, mahsulotlar, hujjatlar va buyurtmalar bir joyda.</p></div><div class="dashboard-shell"><nav class="dashboard-nav"><button data-action="admin-tab" data-tab="overview" class="${tab==='overview'?'active':''}">${icon('grid')} Umumiy</button><button data-action="admin-tab" data-tab="sellers" class="${tab==='sellers'?'active':''}">${icon('store')} Sotuvchilar ${s.seller_requests?`(${s.seller_requests})`:''}</button><button data-action="admin-tab" data-tab="products" class="${tab==='products'?'active':''}">${icon('box')} Mahsulotlar ${s.pending_products?`(${s.pending_products})`:''}</button><button data-action="admin-tab" data-tab="orders" class="${tab==='orders'?'active':''}">${icon('truck')} Buyurtmalar</button>${Object.entries(cmsTabs).map(([key,[glyph,label]])=>`<button data-action="admin-tab" data-tab="${key}" class="${tab===key?'active':''}">${icon(glyph)} ${label}</button>`).join('')}</nav><div class="dashboard-main">${tab==='sellers'?sellerTable:tab==='products'?productTable:tab==='orders'?orderTable:cmsTabs[tab]?MarketuzCMS.render(tab,settings,icon,esc):`${stats}<div class="dashboard-card"><h2>Tezkor boshqaruv</h2><div class="hero-buttons"><a href="/admin?tab=seasons" data-link class="btn btn-soft">Mavsumiy dizayn</a><a href="/admin?tab=brand" data-link class="btn btn-soft">Brend va SEO</a><a href="/admin?tab=products" data-link class="btn btn-soft">${s.pending_products} ta mahsulot tekshiruvda</a></div></div>`}</div></div>`;
}
function renderDelivery() {
  updateTitle('Yetkazib berish');
  return `${crumbs(['Yetkazib berish'])}<div class="page-heading"><span class="eyebrow">Butun O‘zbekiston uchun</span><h1>Yetkazib berish</h1><p>Mahsulotingiz manzilga qanday yetib borishini qulay kuzating.</p></div><div class="delivery-hero"><span class="eyebrow eyebrow-light">Qulay jarayon</span><h1>Siz tanlang, qolganini birgalikda hal qilamiz.</h1><p>Jo‘natish xizmati, hudud, muddat va narx har bir buyurtma bo‘yicha alohida tasdiqlanadi.</p></div><div class="steps"><div class="step"><span class="benefit-icon">${icon('bag')}</span><strong>Mahsulot tanlang</strong><p>O‘zingizga yoqqanlarini savatga yig‘ing va buyurtma so‘rovini yuboring.</p></div><div class="step"><span class="benefit-icon">${icon('check')}</span><strong>Operator tasdiqlaydi</strong><p>Mavjudlik, yetkazish hududi, muddati va narxi siz bilan kelishiladi.</p></div><div class="step"><span class="benefit-icon">${icon('truck')}</span><strong>Jo‘natmani kuzating</strong><p>Kuzatuv raqami taqdim etilgach uni shaxsiy kabinetda ko‘rasiz.</p></div></div><div class="legal-card"><h2>UzPost bilan yetkazish rejasi</h2><p>Platforma UzPost bilan shartnoma asosida ishlashga mo‘ljallangan. Shartnoma va texnik hujjatlar olinguncha jo‘natmalar avtomatik yaratilmaydi, muddat va narx kafolatlanmaydi. Administrator jo‘natma holati va kuzatuv raqamini qo‘lda yangilashi mumkin.</p><h2>Qaysi hududlar?</h2><p>Buyurtma shaklida O‘zbekistonning barcha viloyatlari, Toshkent shahri va Qoraqalpog‘iston tanlanadi. Muayyan manzilga xizmat mavjudligi buyurtma tasdiqlanganda aniqlanadi.</p><a href="/catalog" data-link class="btn btn-primary">Xaridni boshlash</a></div>`;
}
function renderLegal(which) {
  const privacy=which==='privacy',legal=state.config.site.legal; updateTitle(privacy?'Maxfiylik siyosati':'Foydalanish shartlari');
  return `${crumbs([privacy?'Maxfiylik siyosati':'Foydalanish shartlari'])}<div class="page-heading"><span class="eyebrow">Ochiq va tushunarli</span><h1>${privacy?'Maxfiylik siyosati':'Foydalanish shartlari'}</h1><p>Oxirgi tahrir: ${new Date(legal.effectiveDate+'T00:00:00Z').toLocaleDateString('uz-UZ',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'})}</p></div><div class="legal-wrap"><aside class="legal-side"><strong>Ma’lumotlar</strong><a href="/terms" data-link>Foydalanish shartlari</a><a href="/privacy" data-link>Maxfiylik siyosati</a><a href="/delivery" data-link>Yetkazib berish</a><p>Operator rekvizitlari va aloqa ma’lumotlari admin panelda ko‘rsatiladi.</p></aside><article class="legal-card">${privacy?`
    <h1>Sizning ma’lumotlaringiz</h1><p class="legal-note">Platforma operatori haqidagi ma’lumotlar quyida ko‘rsatiladi. Karta ma’lumotlari Marketuz serveriga yuborilmaydi.</p>
    <h2>1. Qanday ma’lumotlar olinadi?</h2><p>Hisob ochganda ism, email va parolning kriptografik xeshi; profilga kiritilsa telefon raqami; buyurtma so‘rovida qabul qiluvchi ismi, telefon, hudud, manzil va buyurtma tarkibi saqlanadi. Parolning o‘zi bazada saqlanmaydi. Karta ma’lumotlari olinmaydi.</p>
    <h2>2. Nima uchun ishlatiladi?</h2><p>Hisobga kirish, savdo oqimini tashkil etish, buyurtmani tasdiqlash, sotuvchi va yetkazuvchi bilan kerakli tafsilotlarni ulashish, xavfsizlik va xizmat ko‘rsatish uchun. Marketing xabarlari alohida roziliksiz yuborilmaydi.</p>
    <h2>3. Kimlar ko‘radi?</h2><p>Administrator buyurtma va aloqa ma’lumotlarini, tegishli sotuvchi esa o‘z mahsulotiga doir buyurtma ma’lumotlarini ko‘rishi mumkin. Yetkazish bo‘yicha shartnoma tuzilgandan keyin jo‘natish uchun zarur ma’lumotlar xizmat ko‘rsatuvchiga berilishi mumkin.</p>
    <h2>4. Saqlash va himoya</h2><p>Ma’lumotlar alohida ma’lumotlar bazasida saqlanadi. Sessiyalar HttpOnly cookie bilan yuritiladi, parollar scrypt xeshi sifatida saqlanadi. Xosting hududi O‘zbekistondan tashqarida bo‘lishi mumkin; operator mahalliylashtirish va transchegaraviy ishlov berish masalalarini rasmiylashtirishi zarur.</p>
    <h2>5. Sizning tanlovingiz</h2><p>Profil ma’lumotlarini kabinetda yangilashingiz mumkin. Ma’lumotlarga kirish, tuzatish yoki o‘chirish uchun operatorning rasmiy aloqa kanali ishga tushirilgach murojaat qiling. Murojaat kanali quyida keltiriladi.</p>
    <h2>6. Huquqiy asos</h2><p>Shaxsga doir ma’lumotlarga ishlov berishda amaldagi O‘zbekiston qonunchiligi hisobga olinadi. <a href="https://lex.uz/uz/docs/-4396419" target="_blank" rel="noopener noreferrer">“Shaxsga doir ma’lumotlar to‘g‘risida”gi qonun</a> bilan tanishing.</p>`: `
    <h1>Platformadan foydalanish</h1><p class="legal-note">Platforma operatorining rekvizitlari va qaytarish tartibi quyida keltiriladi. Yetkazish shartlari buyurtma bo‘yicha tasdiqlanadi.</p>
    <h2>1. Platforma va hisob</h2><p>Marketuz xaridorlar va sotuvchilarni bog‘lovchi marketplace sifatida ishlab chiqilmoqda. Xaridor hisob ochishi, katalogni ko‘rishi, savatga qo‘shishi va buyurtma so‘rovini yuborishi mumkin. Hisob egasi parolini sir saqlaydi.</p>
    <h2>2. Mahsulot va sotuvchilar</h2><p>Sotuvchi arizasi administrator tomonidan tasdiqlanadi. Sotuvchi o‘zi joylashtirgan mahsulot ma’lumotlari, rasm va qonuniy savdosi uchun javobgar bo‘ladi. Mahsulot e’lonlari tasdiqlashdan keyin katalogda ko‘rinadi. Yetkazish narxi manzilga qarab hisoblanadi.</p>
    <h2>3. Buyurtma va to‘lov</h2><p>Buyurtma yuborish dastlabki so‘rovdir. Mahsulot mavjudligi, yetkazish hududi, narxi va muddati alohida tasdiqlanadi. Onlayn to‘lov provayderlari faollashtirilgandagina ko‘rsatiladi. Karta rekvizitlari provayder sahifasida kiritiladi; Marketuz ularni saqlamaydi.</p>
    <h2>4. Yetkazish va qaytarish</h2><p>UzPost bilan shartnoma va API ulanishi rejalashtirilgan. Hozir jo‘natma avtomatik rasmiylashtirilmaydi. Buyurtmaning yetkazish narxi va qaytarish tartibi operator tomonidan bildiriladi. Buyurtmani jo‘natishdan oldin kabinet orqali bekor qilish mumkin.</p>
    <h2>5. Ruxsat etilmagan harakatlar</h2><p>Soxta mahsulot e’lonlari, noqonuniy yoki boshqalarning huquqini buzuvchi kontent joylash, boshqa hisobga ruxsatsiz kirish va xizmat ishiga zarar yetkazish taqiqlanadi.</p>
    <h2>6. Amaldagi huquq</h2><p>Faoliyat O‘zbekistonning amaldagi qonunchiligi asosida yo‘lga qo‘yilishi ko‘zda tutilgan. <a href="https://lex.uz/docs/-6213382" target="_blank" rel="noopener noreferrer">“Elektron tijorat to‘g‘risida”gi qonun</a> bilan tanishing.</p>`}<h2>Platforma operatori</h2><p>${legal.operator?esc(legal.operator):'Yuridik operator rekvizitlari hozircha kiritilmagan.'} ${legal.taxId?`· STIR: ${esc(legal.taxId)}`:''}</p><p>${esc(legal.address||'Manzil ko‘rsatilmagan.')} ${esc(legal.phone||'')} ${esc(legal.email||'')}</p>${!privacy&&legal.returnPolicy?`<h2>Qaytarish tartibi</h2><p>${esc(legal.returnPolicy)}</p>`:''}${(privacy?legal.privacyExtra:legal.termsExtra)?`<h2>Qo‘shimcha qoidalar</h2><p>${esc(privacy?legal.privacyExtra:legal.termsExtra)}</p>`:''}</article></div>`;
}

async function render() {
  const id=++state.request; headerUpdate(); app.innerHTML='<div class="loading-state">Sahifa yuklanmoqda...</div>';
  try {
    const pathname=location.pathname; let html;
    if(pathname==='/') html=await renderHome();
    else if(pathname==='/catalog') html=await renderCatalog();
    else if(pathname.startsWith('/product/')) html=await renderProduct(pathname.split('/')[2]);
    else if(pathname==='/cart') html=await renderCart();
    else if(pathname==='/checkout') html=await renderCheckout();
    else if(pathname==='/favorites') html=await renderFavorites();
    else if(pathname==='/account') html=await renderAccount();
    else if(pathname==='/seller') html=await renderSeller();
    else if(pathname==='/admin') html=await renderAdmin();
    else if(pathname==='/delivery') html=renderDelivery();
    else if(pathname==='/terms'||pathname==='/privacy') html=renderLegal(pathname.slice(1));
    else { updateTitle('Sahifa topilmadi'); html=empty('Sahifa topilmadi','Manzilni tekshirib ko‘ring.','Bosh sahifa','/','search'); }
    if(id===state.request) { app.innerHTML=html; headerUpdate(); $('#search-input').value=new URLSearchParams(location.search).get('q')||''; }
  } catch(e) { if(id===state.request) app.innerHTML=`${empty('Sahifani ochib bo‘lmadi',e.message,'Qayta urinish',location.pathname+location.search,'clock')}`; }
}

function formValues(form) { return Object.fromEntries(new FormData(form).entries()); }
function collectLinks(v){return [1,2,3].map(n=>({label:v['linkLabel'+n]?.trim(),url:v['linkUrl'+n]?.trim()})).filter(x=>x.label&&x.url);}
function openPayment(url){
  if(!/^https:\/\/(checkout\.paycom\.uz|my\.click\.uz)\//.test(url)) return notify('To‘lov havolasi xato.',true);
  const tg=window.Telegram?.WebApp;
  if(tg?.initData) tg.openLink(url);
  else if(window.ReactNativeWebView) window.ReactNativeWebView.postMessage(JSON.stringify({type:'marketuz:openExternal',url}));
  else window.open(url,'_blank','noopener,noreferrer');
}
async function submitForm(form) {
  const kind=form.dataset.form, v=formValues(form), btn=form.querySelector('button[type="submit"]'); if(btn) btn.disabled=true;
  try {
    if(kind==='login'||kind==='register') {
      const payload=kind==='register'?{ name:v.name,email:v.email,password:v.password,agree:!!v.agree }:{email:v.email,password:v.password};
      const {user}=await api('/auth/'+(kind==='register'?'register':'login'),{method:'POST',body:JSON.stringify(payload)}); state.user=user;
      if(user.role==='admin'||user.role==='seller') { /* role navigation is available in the menu */ }
      try { const f=await api('/favorites'); state.favorites=new Set(f.products.map(p=>String(p.id))); } catch {}
      notify('Xush kelibsiz!'); nav(state.authNext||'/account'); state.authNext=null;
    } else if(kind==='checkout') {
      const products=await loadCart();
      const order=await api('/orders',{method:'POST',body:JSON.stringify({ ...v, items:products.map(x=>({id:x.id,qty:x.qty})) })});
      state.cart=[]; saveLocal('marketuz_cart',state.cart); notify(order.message); nav('/account?tab=orders'); if(order.paymentUrl) openPayment(order.paymentUrl);
    } else if(kind==='profile') { const {user}=await api('/me',{method:'PATCH',body:JSON.stringify(v)}); state.user=user; notify('Profil saqlandi.'); render(); }
    else if(kind==='password') { await api('/me/password',{method:'POST',body:JSON.stringify(v)}); form.reset(); notify('Parol yangilandi.'); }
    else if(kind==='seller-product') { const editId=form.dataset.editId; await api('/seller/products'+(editId?'/'+editId:''),{method:editId?'PATCH':'POST',body:JSON.stringify({...v,externalLinks:collectLinks(v)})}); notify('Mahsulot tekshiruvga yuborildi.'); render(); }
    else if(kind==='admin-order') { await api('/admin/orders/'+form.dataset.id,{method:'PATCH',body:JSON.stringify(v)}); notify('Buyurtma holati saqlandi.'); render(); }
    else if(kind==='admin-product-details') { await api('/admin/products'+(form.dataset.editId?'/'+form.dataset.editId+'/details':''),{method:form.dataset.editId?'PATCH':'POST',body:JSON.stringify({...v,externalLinks:collectLinks(v)})}); notify('Mahsulot saqlandi.'); render(); }
    else if(kind==='site-settings') { const next=MarketuzCMS.collect(form,state.admin.settings.site); const result=await api('/admin/settings',{method:'PATCH',body:JSON.stringify(next)}); state.config.site=result.site;state.config.categories=result.site.categories;state.config.seasonal=result.seasonal;applySite();notify('Sayt sozlamalari saqlandi.');render(); }
  } catch(e) { notify(e.message,true); } finally { if(btn) btn.disabled=false; }
}
async function actionOf(button) {
  const action=button.dataset.action,id=button.dataset.id;
  if(action==='menu') return openMenu(); if(action==='menu-close') return closeMenu();
  if(action==='auth-mode') return nav('/account?mode='+button.dataset.mode);
  if(action==='add-cart') { const p=state.products.get(String(id))||(await api('/products/'+id)).product; if(p.stock<1) return notify('Mahsulot hozircha tugagan.',true); const item=state.cart.find(x=>String(x.id)===String(id)); if(item) item.qty=Math.min(Math.min(p.stock,20),Number(item.qty)+1); else state.cart.push({id:Number(id),qty:1}); saveLocal('marketuz_cart',state.cart); headerUpdate(); notify('Mahsulot savatga qo‘shildi.'); return; }
  if(action==='resume-payment'){const {url}=await api('/orders/'+id+'/payment-link');openPayment(url);return;}
  if(action==='share') {const p=state.products.get(String(id)),url=location.origin+'/product/'+id;if(navigator.share){try{await navigator.share({title:p?.name||'Marketuz',text:p?.name,url});return;}catch(e){if(e.name==='AbortError')return;}}await navigator.clipboard.writeText(url);notify('Mahsulot havolasi nusxalandi.');return;}
  if(action==='cart-remove') { state.cart=state.cart.filter(x=>String(x.id)!==String(id)); saveLocal('marketuz_cart',state.cart); return render(); }
  if(action==='cart-qty') { const item=state.cart.find(x=>String(x.id)===String(id)); if(item) { item.qty=Math.max(1,Math.min(Math.min(state.products.get(String(id))?.stock||20,20),Number(item.qty)+Number(button.dataset.delta))); saveLocal('marketuz_cart',state.cart); render(); } return; }
  if(action==='favorite') { const key=String(id), active=state.favorites.has(key); if(state.user) await api('/favorites/'+id,{method:active?'DELETE':'PUT',body:'{}'}); if(active) state.favorites.delete(key); else state.favorites.add(key); saveLocal('marketuz_favorites',[...state.favorites]); notify(active?'Sevimlilardan olib tashlandi.':'Sevimlilarga qo‘shildi.'); if(location.pathname==='/favorites') render(); else { button.classList.toggle('active',!active); button.setAttribute('aria-label',active?'Sevimlilarga qo‘shish':'Sevimlilardan olib tashlash'); } return; }
  if(action==='logout') { await api('/auth/logout',{method:'POST',body:'{}'}); state.user=null; state.favorites=new Set(); saveLocal('marketuz_favorites',[]); notify('Hisobdan chiqildi.'); nav('/'); return; }
  if(action==='cancel-order') { if(!confirm('Buyurtmani bekor qilasizmi?')) return; await api('/orders/'+id+'/cancel',{method:'POST',body:'{}'}); notify('Buyurtma bekor qilindi.'); render(); return; }
  if(action==='seller-request') { await api('/seller/request',{method:'POST',body:'{}'}); state.user.seller_status='pending'; notify('Ariza yuborildi.'); render(); return; }
  if(action==='seller-tab') return nav('/seller?tab='+button.dataset.tab);
  if(action==='admin-tab') return nav('/admin?tab='+button.dataset.tab);
  if(action==='category-add') {MarketuzCMS.addCategory($('#cms-categories'));return;}
  if(action==='category-remove') {button.closest('[data-category-row]')?.remove();return;}
  if(action==='seller-new') { const card=$('#seller-form-card'); if(card){card.hidden=false; card.querySelector('form').reset(); card.querySelector('form').removeAttribute('data-edit-id'); $('#seller-form-title').textContent='Mahsulot qo‘shish'; card.scrollIntoView({behavior:'smooth'});} return; }
  if(action==='seller-form-close') { $('#seller-form-card').hidden=true; return; }
  if(action==='seller-edit') { const p=state.sellerProducts.find(x=>String(x.id)===String(id)); if(!p) return; const card=$('#seller-form-card'),form=card.querySelector('form'); card.hidden=false; form.dataset.editId=id; $('#seller-form-title').textContent='Mahsulotni tahrirlash'; for(const [name,val] of Object.entries({name:p.name,description:p.description,category:p.category,price:p.price,oldPrice:p.old_price||'',stock:p.stock,image:p.image_url})) form.elements[name].value=val; (p.external_links||[]).slice(0,3).forEach((l,i)=>{form.elements['linkLabel'+(i+1)].value=l.label;form.elements['linkUrl'+(i+1)].value=l.url;}); card.scrollIntoView({behavior:'smooth'}); return; }
  if(action==='seller-archive') { if(!confirm('Mahsulot arxivlansinmi?')) return; await api('/seller/products/'+id,{method:'DELETE',body:'{}'}); notify('Mahsulot arxivlandi.'); render(); return; }
  if(action==='seller-item-status') { await api('/seller/order-items/'+id,{method:'PATCH',body:JSON.stringify({status:button.dataset.status})}); notify('Tayyorlash holati o‘zgardi.'); render(); return; }
  if(action==='admin-seller') { await api('/admin/sellers/'+id,{method:'PATCH',body:JSON.stringify({status:button.dataset.status})}); notify('Sotuvchi arizasi yangilandi.'); render(); return; }
  if(action==='admin-product') { await api('/admin/products/'+id,{method:'PATCH',body:JSON.stringify({status:button.dataset.status})}); notify('Mahsulot holati yangilandi.'); render(); return; }
  if(action==='admin-new-product'){const card=$('#admin-product-card');card.hidden=false;const form=card.querySelector('form');form.reset();delete form.dataset.editId;card.querySelector('h2').textContent='Mahsulot qo‘shish';card.scrollIntoView({behavior:'smooth'});return;}
  if(action==='admin-edit-product') {const p=state.admin.products.find(x=>String(x.id)===String(id)),card=$('#admin-product-card');if(!p||!card)return;card.hidden=false;card.querySelector('h2').textContent='Mahsulotni tahrirlash';const form=card.querySelector('form');form.reset();form.dataset.editId=id;for(const [k,v] of Object.entries({name:p.name,description:p.description,category:p.category,stock:p.stock,price:p.price,oldPrice:p.old_price||'',image:p.image_url,status:p.status}))form.elements[k].value=v;(p.external_links||[]).slice(0,3).forEach((l,i)=>{form.elements['linkLabel'+(i+1)].value=l.label;form.elements['linkUrl'+(i+1)].value=l.url;});card.scrollIntoView({behavior:'smooth'});return;}
  if(action==='upload-asset') {const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>1_500_000)return notify('Rasm 1.5 MB dan kichik bo‘lsin.',true);const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});try{const r=await api('/admin/assets',{method:'POST',body:JSON.stringify({data})});const target=document.querySelector(`[data-setting="${button.dataset.target}"]`);if(target){target.value=r.url;const preview=target.parentElement.querySelector('img');if(preview)preview.src=r.url;}notify('Rasm yuklandi. Sozlamalarni saqlang.');}catch(e){notify(e.message,true);}};input.click();return;}
}

document.addEventListener('click',event=>{
  const link=event.target.closest('a[data-link]'); if(link && !event.ctrlKey && !event.metaKey && !event.shiftKey && event.button===0) { event.preventDefault(); nav(link.pathname+link.search+link.hash); return; }
  const button=event.target.closest('[data-action]'); if(button) { event.preventDefault(); Promise.resolve(actionOf(button)).catch(e=>notify(e.message,true)); }
});
document.addEventListener('submit',event=>{
  if(event.target.id==='header-search'||event.target.id==='mobile-search-form') { event.preventDefault(); nav('/catalog?q='+encodeURIComponent(new FormData(event.target).get('q')||'')); return; }
  if(event.target.dataset.form) { event.preventDefault(); submitForm(event.target); }
});
document.addEventListener('change',event=>{if(event.target.id==='catalog-sort'){const x=new URLSearchParams(location.search);x.set('sort',event.target.value);x.delete('page');nav('/catalog?'+x.toString());}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
$('#drawer-backdrop').addEventListener('click',closeMenu);
window.addEventListener('popstate',()=>{closeMenu();render();});
document.addEventListener('error',event=>{if(event.target.tagName==='IMG' && !event.target.dataset.fallback){ event.target.dataset.fallback='true'; event.target.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="700" height="700"><defs><linearGradient id="g"><stop stop-color="#dfe9d7"/><stop offset="1" stop-color="#f6e6d1"/></linearGradient></defs><rect width="700" height="700" fill="url(#g)"/><circle cx="540" cy="120" r="165" fill="#fff" opacity=".4"/><text x="50%" y="51%" text-anchor="middle" fill="#396652" font-family="sans-serif" font-size="54" font-weight="bold">marketuz ✳</text></svg>');}},true);
$('#year').textContent=new Date().getFullYear();
for(const slot of document.querySelectorAll('[data-icon]')) slot.innerHTML=icon(slot.dataset.icon);
async function start() {
  try { state.config=await api('/config');applySite();const tg=window.Telegram?.WebApp;if(tg?.initData){tg.ready();tg.expand();try{tg.setHeaderColor('#153d37');}catch{}} if(!state.config.demoOnly) { try { state.user=(await api('/me')).user; } catch {} if(!state.user && tg?.initData && state.config.telegramEnabled){try{state.user=(await api('/auth/telegram',{method:'POST',body:JSON.stringify({initData:tg.initData})})).user;}catch(e){notify(e.message,true);}} if(state.user){try{const f=await api('/favorites');state.favorites=new Set(f.products.map(p=>String(p.id)));}catch{}} } await render();if(window.ReactNativeWebView)window.ReactNativeWebView.postMessage(JSON.stringify({type:'marketuz:ready',title:state.config.site.brand.name}));if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{}); }
  catch(e) { app.innerHTML=empty('Ulanishda xatolik',e.message,'Qayta yuklash','/','clock'); }
}
start();
